import React, { useEffect, useState } from "react";
import axios from "axios";

// Адрес Yandex Cloud Function (см. yandex-function/index.js).
// Сам API-ключ Yandex Translate хранится в переменной окружения функции,
// а не здесь, чтобы он не попал в публичный код на GitHub Pages.
const TRANSLATE_URL = "https://functions.yandexcloud.net/d4eri4geutjod8cc3774";

const doTranslation = async (input, languageCode, cancelToken) => {
  try {
    const { data } = await axios.get(TRANSLATE_URL, {
      params: {
        text: input,
        lang: languageCode
      },
      cancelToken: cancelToken.token
    });

    return data.text;
  } catch (err) {
    return "";
  }
};

export default ({ language, text }) => {
  const [translated, setTranslated] = useState("");

  useEffect(() => {
    if (!text) {
      setTranslated("");
      return;
    }

    const cancelToken = axios.CancelToken.source();

    doTranslation(text, language, cancelToken).then(setTranslated);

    return () => {
      try {
        cancelToken.cancel();
      } catch (err) {}
    };
  }, [text, language]);

  return <h1 className="title">{translated}</h1>;
};
